\lambda_n^{1- \alpha} \left({\rm th }\frac{\rho(x,y)}{2}\right)^{\alpha}
\,,
\end{equation}
\begin{equation} \label{my11.2(2)}
\rho(f(x),f(y)) \le K(\rho(x,y) + \log 4)\,,
\end{equation}
